mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM tbl_dim_repository
    WHERE project_id = #{projectId}
      AND delete_flag = FALSE
      AND deleted_at IS NULL
      AND status = 'ACTIVE'
      AND LOWER(BTRIM(repo_name_masked)) = LOWER(BTRIM(#{repoNameMasked}))

          AND repository_id <> #{excludeRepositoryId}

)
